inline bool nativeCareerSegment(const Json& car,const std::string& segment){if(segment=="budget")return basePrice(car)<=300000;if(segment=="electric")return lowerCatalogue(car.value("desc","")).find("электро")!=std::string::npos;if(segment=="suv"){auto body=car.value("body","");return body.find("кроссовер")!=std::string::npos||body.find("внедорожник")!=std::string::npos||std::regex_search(car.value("name",""),std::regex("RAV4|Duster|Land Cruiser|Tiguan|Sportage|CR-V|Forester|Outlander|Haval|Chery Tiggo|CX-|X5|X7|X-Trail|Патриот",std::regex::icase));}return false;}
inline void applyNativeCareerMarket(Json& car,int cycle){if(!car.contains("careerSessionPrice")){car["careerSessionPrice"]=car.at("price");car["careerSessionMarket"]=num(car,"marketPrice",num(car,"price"));}int event=cycle%6;double factor=event==1&&nativeCareerSegment(car,"suv")?1.08:event==3&&nativeCareerSegment(car,"budget")?1.1:event==4&&nativeCareerSegment(car,"electric")?.92:1.;for(const auto& pair:{std::pair<const char*,const char*>{"price","careerSessionPrice"},{"marketPrice","careerSessionMarket"}})car[pair.first]=std::clamp(jsRound(num(car,pair.second)*factor/500)*500,10000.,99000000.);}
inline double nativeCareerFx(const Json& s){int i=s.at("career").value("cycle",0)%6;return i==2?1.07:i==4?.96:1.;}
inline double nativeCareerDealerFactor(const Json& s){return s.at("career").value("cycle",0)%6==5?.97:1.;}
inline bool nativeCareerCarMatches(const Json& s,const Json& order,const Json& car,const Json& offers){auto key=std::to_string(car.at("id").get<Money>());Money basis=s.at("purchasePrices").contains(key)?s.at("purchasePrices").at(key).get<Money>():Money(basePrice(car));if(basis>order.at("budget").get<Money>()-order.at("fee").get<Money>())return false;std::string type=order.value("type","");if(type=="import"){auto acquisition=commerceAcquisition(s.at("commerce"),offers,car.at("id"));if(!acquisition.is_object()||offers.at(acquisition.at("offerId").get<std::string>()).value("kind","")!="import")return false;}if(type=="model"){auto name=lowerCatalogue(car.value("name","")),prefix=lowerCatalogue(order.value("brand","")+" "+order.value("model",""));if(name.compare(0,prefix.size(),prefix)!=0||(name.size()>prefix.size()&&name[prefix.size()]!=' '&&name[prefix.size()]!=','))return false;}if(type=="family"&&!nativeCareerSegment(car,"suv"))return false;if(type=="project"||car.value("newCar",false))return true;const auto& vehicles=s.at("career").at("vehicles");if(!vehicles.contains(key))return false;const auto& v=vehicles[key];auto story=nativeCarStory(car);if(!v.value("inspected",false)||(!story.value("defect","").empty()&&!v.value("repaired",false)))return false;const auto& risks=s.at("marketRisks").at("vehicles");return !risks.contains(key)||!risks[key].value("purchased",false)||!risks[key].value("defect",false)||!risks[key].value("discovered",false)||risks[key].value("repaired",false);}
inline bool fulfillNativeCareerOrder(Json& s,const std::string& orderId,Money carId,const std::string& signature,bool acknowledged,const Json& cities,const Json& cars,const Json& offers,const std::string& home,const std::function<void(const Json&)>& persist){auto k=std::to_string(carId);if(!acknowledged||!validIdentity(s.at("playerIdentity"))||s.at("playerIdentity").at("signature")!=signature||!validSignature(Json(signature))||!cars.contains(k)||!careerLocalCar(s,carId))return false;Json d=s;tickNativeCareer(d);Json* order=nullptr;for(auto& o:d["career"]["orders"])if(o.value("id","")==orderId){order=&o;break;}if(!order||order->value("status","")!="active"||num(d,"gameMs")>=num(*order,"deadline")||order->at("cityId")!=d["transport"]["cityId"]||!nativeCareerCarMatches(d,*order,cars.at(k),offers))return false;
 const auto car=cars.at(k);Money basis=d["purchasePrices"].contains(k)?d["purchasePrices"][k].get<Money>():Money(basePrice(car));Money price=basis+order->at("fee").get<Money>();Json orderCopy=*order;std::string recordId="client-sale-"+orderId;for(const auto& record:d["contracts"]["records"])if(record.value("id","")==recordId)return false;
 // Orders always disclose condition, independently of an earlier public listing.
 if(d["listings"].contains(k))d["listings"][k]["disclosed"]=true;
 Deals deals(cities,cars,home,[]{return .5;});auto plan=deals.plan(d,"sell",carId,price);if(!plan.ok)return false;
 applyCareerDealEffects(plan.state,plan.effects,cars);auto& c=plan.state["career"];for(auto& o:c["orders"])if(o["id"]==orderId){o["status"]="completed";o["carId"]=carId;o["completedAt"]=d["gameMs"];o["price"]=price;}c["clients"][orderCopy.at("client").get<std::string>()]=c["clients"].value(orderCopy.at("client").get<std::string>(),0)+1;c["reputation"]=std::min(100.,num(c,"reputation")+2);c["revision"]=num(c,"revision")+1;
 auto city=cities.at(orderCopy.at("cityId").get<std::string>());auto vehicle=contractDocumentIds(carId,car.value("cityId",home)==home);vehicle["name"]=car.value("name","");vehicle["description"]=car.value("desc","");if(auto color=nativeFactoryColorInfo(nativeFactoryColor(d,car,offers)))vehicle["color"]=color->name;Json seller=plan.state["contracts"]["profile"];seller["fullName"]=d["playerIdentity"]["nickname"];seller["signature"]=signature;auto buyer=contractOtherParty({{"name",orderCopy["client"]}},city);buyer["signature"]=Json::array({Json::array({Json::array({.12,.7}),Json::array({.25,.3}),Json::array({.35,.65}),Json::array({.55,.25}),Json::array({.8,.55})})});
 auto& book=plan.state["contracts"];Money seq=Money(num(book,"sequence"))+1;book["sequence"]=seq;std::string number=std::to_string(seq);if(number.size()<5)number=std::string(5-number.size(),'0')+number;Json record={{"version",1},{"id",recordId},{"number","ЗАК-"+number},{"mode","sell"},{"channel","client"},{"carId",carId},{"city",city.at("name")},{"createdAt",d["gameMs"]},{"signedAt",d["gameMs"]},{"price",price},{"purchasePrice",basis},{"vehicle",vehicle},{"seller",seller},{"buyer",buyer}};
 auto acquisition=commerceAcquisition(d["commerce"],offers,carId);if(acquisition.is_object()){record["costIncludesExpenses"]=true;record["costBreakdown"]=acquisition["costs"];}const auto& prep=d["career"]["vehicles"];Money paid=prep.contains(k)?Money(num(prep[k],"repairPaid")):0;if(paid){record["costIncludesExpenses"]=true;if(!record.contains("costBreakdown"))record["costBreakdown"]={{"vehicle",basis-paid}};record["costBreakdown"]["preparation"]=paid;}
 book["records"].insert(book["records"].begin(),record);while(book["records"].size()>100)book["records"].erase(book["records"].end()-1);if(plan.state.contains("chat")&&plan.state["chat"].is_object()&&plan.state["chat"].contains("car")&&plan.state["chat"]["car"].value("id",0LL)==carId){plan.state["chat"]["done"]=true;plan.state["chat"]["stage"]="done";}
 persist(plan.state);s.swap(plan.state);return true;
}
